csui.define('csui/controls/tablesettings/menu.item.views/table.settings.menu.checkbox.view',[
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'smart/utils/otwc.loader',
  'hbs!csui/controls/tablesettings/menu.item.views/impl/table.settings.menu.item',
], function (_, Backbone, Marionette, otwcLoader, template) {
  'use strict';
  const TableSettingsMenuCheckboxView = Marionette.ItemView.extend({
    template: template,
    tagName: 'otc-menucheckbox',
    attributes: function () {
      return {
        checked: this.model.get('checked'),
      }
    },

    constructor: function TableSettingsMenuCheckboxView(options) {
      // check mandatory parameters
      if (!options) {
        throw new Error('options object is mandatory for TableSettingsMenuCheckboxView');
      }

      Marionette.ItemView.prototype.constructor.call(this, options);
      this.listenTo(this.model, 'change', (eventData) => {
        if (eventData.changed.checked === undefined) {
          // checked attribute has not changed. Only if there is at least one other item, call render
          if (Object.keys(eventData.changed).length > 0) {
            this.render();
          }
        } else {
          // if checked has changed and at least one more other attribute, call render and set the checked property
          // on the root element (which is the web component root)
          if (Object.keys(eventData.changed).length > 1) {
            this.render();
          }
          this.el.checked = !!this.model.get('checked');
        }
      });
    },

    events: {
      'change': 'onChanged',
    },

    onChanged: function (event) {
      const checked = event.originalEvent.detail.checked;
      if (checked !== this.model.get('checked')) {
        // only trigger the event if the checked state has changed
        this.trigger('change:switch', {"checked": checked});
      }
    },

  });
  return TableSettingsMenuCheckboxView;
});
