csui.define('csui/widgets/recycle.items.table/recycle.items.columns',["csui/lib/backbone"], function (Backbone) {

  var TableColumnModel = Backbone.Model.extend({

    idAttribute: "key",

    defaults: {
      key: null,  // key from the resource definitions
      sequence: 0 // smaller number moves the column to the front
    }

  });

  var TableColumnCollection = Backbone.Collection.extend({

    model: TableColumnModel,
    comparator: "sequence",

    getColumnKeys: function () {
      return this.pluck('key');
    },

    deepClone: function () {
      // using js map
      return new TableColumnCollection(this.models?.map(column =>
        {column.attributes} ));
    }

  });

  const RecycleItemsTableColumns = new TableColumnCollection([
    {
      key: 'type',
      sequence: 10
    },
    {
      key: 'name',
      sequence: 20
    },
    {
      key: 'deleted_date',
      sequence: 40
    },
    {
      key: 'deleted_user_name',
      sequence: 50
    },
    {
      key: 'created_by_user_name',
      sequence: 60
    },
    {
      key: 'size',
      sequence: 70
    },
    {
      key: 'parent_id',
      sequence: 80
    },
    {
      key: 'purged_date',
      sequence: 90
    }
  ]);

  return RecycleItemsTableColumns;

});